// djb2 hash function
size_t rcutils_hash_map_string_hash_func(const void * key_str)
{
  const char ** ckey_ptr = (const char **) key_str;
  const char * ckey_str = *ckey_ptr;
  size_t hash = 5381;

  while ('\0' != *ckey_str) {
    const char c = *(ckey_str++);
    hash = ((hash << 5) + hash) + (size_t)c; /* hash * 33 + c */
  }

