  (void)start_offset;
  (void)end_offset;

  if (logging_input->location && logging_input->location->file_name) {
    const char * file_name = logging_input->location->file_name;
    const char * basename = file_name;
    const char * last_sep = strrchr(file_name, '/');
    if (last_sep != NULL) {
      basename = last_sep + 1;
